prts.feedbackvariables:
student_plane_valid:
not (is(ansa=0) and is(ansb=0) and is(ansc=0));

studentD:
if student_plane_valid
then is(ansa*Dx+ansb*Dy+ansc*Dz=ansd)
else false;

correct_b:is(anscop=coplanar);

consistent_b:
if student_plane_valid
then is(anscop=studentD)
else false;

b_score:
if correct_b and consistent_b then 1
else if correct_b then 2/3
else if consistent_b then 1/2
else 0;

same_ok:
if is(ansc=0)
then false
else is(ansa=ansc*na) and is(ansb=ansc*nb) and is(ansd=ansc*nd);

parallel_ok:
if is(ansc=0)
then false
else is(ansa=ansc*na) and is(ansb=ansc*nb);

plane_score:
if same_ok then 1
else if parallel_ok then 4/7
else 0;
